head.script:
scwin.onpageload = function() {
    scwin.log("[main] onpageload fired");
};

// 모든 wframe 자식이 호출하는 공용 로깅 함수.
// txa_log 가 아직 없으면 window.__pendingLog 큐에 쌓고, 추후 txa_log init 후 flush.
window.__pendingLog = window.__pendingLog || [];
scwin.log = function(msg) {
    var ts = new Date().toISOString().substring(11, 23);
    var line = ts + "  " + msg;
    var t = (typeof txa_log !== "undefined") ? txa_log : null;
    if (t && typeof t.getValue === "function") {
        // pending 먼저 flush
        if (window.__pendingLog.length) {
            var pre = window.__pendingLog.join("\n") + "\n";
            window.__pendingLog.length = 0;
            t.setValue((t.getValue() || "") + pre);
        }
        t.setValue((t.getValue() || "") + line + "\n");
    } else {
        window.__pendingLog.push(line + "  (queued; txa_log not ready)");
    }
};

scwin.btn_clearLog_onclick = function() {
    txa_log.setValue("");
    window.__pendingLog.length = 0;
};

scwin.btn_dumpPending_onclick = function() {
    if (!window.__pendingLog.length) {
        scwin.log("[main] __pendingLog 비어있음 (즉 모든 onpageload 가 txa_log init 후 호출됐거나, 아예 호출되지 않았음)");
        return;
    }
    var snap = window.__pendingLog.slice();
    window.__pendingLog.length = 0;
    snap.forEach(function(l) {
        txa_log.setValue((txa_log.getValue() || "") + "[PENDING] " + l + "\n");
    });
};

scwin.btn_selectOuter2_onclick = async function() {
    scwin.log("[main] outer tab[1] select 호출");
    await tabControl_outer.setSelectedTabIndex(1);
    scwin.log("[main] outer tab[1] select 완료");
};

scwin.btn_selectOuter1_onclick = async function() {
    scwin.log("[main] outer tab[0] select 호출");
    await tabControl_outer.setSelectedTabIndex(0);
    scwin.log("[main] outer tab[0] select 완료");
};
